static inline bool verificar_colisao_f1(int x, int y) {
    if (x < 0 || x >= 320 || y < 0 || y >= 480) {
        return true;
    }
    return paredesF1[y][x] != 0;
}

static inline bool verificar_colisao_box_f1(int x, int y, int largura, int altura) {
    for (int cy = y; cy < y + altura; cy++) {
        for (int cx = x; cx < x + largura; cx++) {
            if (verificar_colisao_f1(cx, cy)) {
                return true;
            }
        }
    }
    return false;
}

